import type { BoardCode } from "./board/code.ts";
import { generateDeck } from "./board/generate.ts";
import type { BoardSize } from "./board/sizes.ts";

export const SELECTION_KINDS = {
  closed: "closed",
  one: "one",
  mismatch: "mismatch",
} as const;

export interface ClosedSelection {
  readonly kind: typeof SELECTION_KINDS.closed;
}

export interface OneSelection {
  readonly kind: typeof SELECTION_KINDS.one;
  readonly index: number;
}

export interface MismatchSelection {
  readonly kind: typeof SELECTION_KINDS.mismatch;
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}

export type GameSelection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameBoard {
  readonly code: string;
  readonly size: BoardSize;
  readonly deck: readonly number[];
}

export interface GameState {
  readonly board: GameBoard;
  readonly matched: readonly number[];
  readonly selection: GameSelection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const CLOSED_SELECTION: ClosedSelection = Object.freeze({
  kind: SELECTION_KINDS.closed,
});

export function createGameFromCode(board: BoardCode): GameState {
  const gameBoard: GameBoard = Object.freeze({
    code: board.value,
    size: board.size,
    deck: generateDeck(board),
  });

  return Object.freeze({
    board: gameBoard,
    matched: Object.freeze([]),
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}
import { parseBoardCode } from "./board/code.ts";
import { createGameFromCode, type GameState } from "./state.ts";

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  return board === null ? null : createGameFromCode(board);
}
import { isBoardSize, type BoardSize } from "./sizes.ts";

export interface BoardCode {
  readonly value: string;
  readonly size: BoardSize;
  readonly seed: number;
}

export function parseBoardCode(value: string): BoardCode | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(value);
  const sizePart = match?.[1];
  const seedPart = match?.[2];

  if (sizePart === undefined || seedPart === undefined) return null;

  const size = Number(sizePart);
  const seed = Number(seedPart);
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > 2147483646) {
    return null;
  }

  return { value, size, seed };
}
import type { BoardCode } from "./code.ts";

export const PARK_MILLER_MODULUS = 2147483647;
const PARK_MILLER_MULTIPLIER = 16807;
const RANDOM_VALUES = PARK_MILLER_MODULUS - 1;

export function nextParkMillerState(state: number): number {
  return (state * PARK_MILLER_MULTIPLIER) % PARK_MILLER_MODULUS;
}

export function generateDeck(board: BoardCode): readonly number[] {
  const cardCount = board.size * board.size;
  const deck = Array.from({ length: cardCount }, (_, index) => Math.floor(index / 2));
  let state = board.seed;

  const draw = (bound: number): number => {
    const limit = Math.floor(RANDOM_VALUES / bound) * bound;
    let sample: number;
    do {
      state = nextParkMillerState(state);
      sample = state - 1;
    } while (sample >= limit);
    return sample % bound;
  };

  for (let index = cardCount - 1; index > 0; index -= 1) {
    const other = draw(index + 1);
    const currentCard = deck[index];
    const otherCard = deck[other];
    if (currentCard !== undefined && otherCard !== undefined) {
      deck[index] = otherCard;
      deck[other] = currentCard;
    }
  }

  return Object.freeze(deck);
}
export const BOARD_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;

export type BoardSize = (typeof BOARD_SIZES)[number];

export function isBoardSize(value: unknown): value is BoardSize {
  return typeof value === "number" && BOARD_SIZES.some((size) => size === value);
}

import {
  CLOSED_SELECTION,
  SELECTION_KINDS,
  isWon,
  type GameState,
} from "./state.ts";

export const MAX_ELAPSED_MS = 359999999;
export const MISMATCH_DURATION_MS = 800;

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (
    !Number.isSafeInteger(milliseconds) ||
    milliseconds <= 0 ||
    !state.started ||
    isWon(state)
  ) {
    return state;
  }

  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection;

  if (selection.kind !== SELECTION_KINDS.mismatch) {
    return Object.freeze({ ...state, elapsedMs });
  }

  if (milliseconds >= selection.remainingMs) {
    return Object.freeze({ ...state, elapsedMs, selection: CLOSED_SELECTION });
  }

  return Object.freeze({
    ...state,
    elapsedMs,
    selection: Object.freeze({
      ...selection,
      remainingMs: selection.remainingMs - milliseconds,
    }),
  });
}
import {
  CLOSED_SELECTION,
  SELECTION_KINDS,
  type GameState,
} from "./state.ts";
import { MISMATCH_DURATION_MS } from "./clock.ts";

export const MAX_MOVES = 999999;

function isMatched(state: GameState, index: number): boolean {
  return state.matched.includes(index);
}

export function activateCard(state: GameState, index: number): GameState {
  if (
    !Number.isSafeInteger(index) ||
    index < 0 ||
    index >= state.board.deck.length ||
    isWon(state) ||
    isMatched(state, index)
  ) {
    return state;
  }

  const selection = state.selection;
  if (selection.kind === SELECTION_KINDS.mismatch) return state;

  if (selection.kind === SELECTION_KINDS.closed) {
    return Object.freeze({
      ...state,
      selection: Object.freeze({ kind: SELECTION_KINDS.one, index }),
      started: true,
    });
  }

  if (selection.index === index) return state;

  const moves = Math.min(MAX_MOVES, state.moves + 1);
  const firstFace = state.board.deck[selection.index];
  const secondFace = state.board.deck[index];

  if (firstFace === secondFace) {
    return Object.freeze({
      ...state,
      matched: Object.freeze([...state.matched, selection.index, index]),
      selection: CLOSED_SELECTION,
      moves,
    });
  }

  return Object.freeze({
    ...state,
    selection: Object.freeze({
      kind: SELECTION_KINDS.mismatch,
      first: selection.index,
      second: index,
      remainingMs: MISMATCH_DURATION_MS,
    }),
    moves,
  });
}
import { parseBoardCode } from "./board/code.ts";
import { createGameFromCode } from "./state.ts";
import { isWon, type GameSelection, type GameState } from "./state.ts";

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65536;
const MAX_MOVES = 999999;
const MAX_ELAPSED_MS = 359999999;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

function isIndex(value: unknown, count: number): value is number {
  return Number.isSafeInteger(value) && typeof value === "number" && value >= 0 && value < count;
}

function isUnknownArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value);
}

function decodeSelection(value: unknown, count: number): GameSelection | null {
  if (!isRecord(value) || typeof value.kind !== "string") return null;

  if (value.kind === "closed" && hasExactKeys(value, ["kind"])) {
    return { kind: "closed" };
  }

  if (
    value.kind === "one" &&
    hasExactKeys(value, ["kind", "index"]) &&
    isIndex(value.index, count)
  ) {
    return { kind: "one", index: value.index };
  }

  if (
    value.kind === "mismatch" &&
    hasExactKeys(value, ["kind", "first", "second", "remainingMs"]) &&
    isIndex(value.first, count) &&
    isIndex(value.second, count) &&
    value.first !== value.second &&
    Number.isSafeInteger(value.remainingMs) &&
    typeof value.remainingMs === "number" &&
    value.remainingMs >= 1 &&
    value.remainingMs <= 800
  ) {
    return {
      kind: "mismatch",
      first: value.first,
      second: value.second,
      remainingMs: value.remainingMs,
    };
  }

  return null;
}

function hasWholeMatchedPairs(
  matched: readonly number[],
  deck: readonly number[],
): boolean {
  const seen = new Set<number>();
  const counts = new Map<number, number>();

  for (const index of matched) {
    if (!isIndex(index, deck.length) || seen.has(index)) return false;
    seen.add(index);
    const face = deck[index];
    if (face === undefined) return false;
    counts.set(face, (counts.get(face) ?? 0) + 1);
  }

  return [...counts.values()].every((count) => count === 2);
}

function decodeMatched(value: unknown, deck: readonly number[]): readonly number[] | null {
  if (!isUnknownArray(value)) return null;
  const indices: number[] = [];
  for (const index of value) {
    if (!isIndex(index, deck.length)) return null;
    indices.push(index);
  }
  return hasWholeMatchedPairs(indices, deck) ? Object.freeze(indices) : null;
}

export function encodeSnapshot(state: GameState): string {
  return JSON.stringify(
    {
      version: SNAPSHOT_VERSION,
      boardCode: state.board.code,
      matched: state.matched,
      selection: state.selection,
      moves: state.moves,
      elapsedMs: state.elapsedMs,
      started: state.started,
    },
    null,
    2,
  );
}

export function decodeSnapshot(text: string): GameState | null {
  if (new TextEncoder().encode(text).byteLength > SNAPSHOT_BYTE_LIMIT) return null;

  let input: unknown;
  try {
    input = JSON.parse(text);
  } catch {
    return null;
  }

  if (
    !isRecord(input) ||
    !hasExactKeys(input, [
      "version",
      "boardCode",
      "matched",
      "selection",
      "moves",
      "elapsedMs",
      "started",
    ]) ||
    input.version !== SNAPSHOT_VERSION ||
    typeof input.boardCode !== "string" ||
    !Number.isSafeInteger(input.moves) ||
    typeof input.moves !== "number" ||
    input.moves < 0 ||
    input.moves > MAX_MOVES ||
    !Number.isSafeInteger(input.elapsedMs) ||
    typeof input.elapsedMs !== "number" ||
    input.elapsedMs < 0 ||
    input.elapsedMs > MAX_ELAPSED_MS ||
    typeof input.started !== "boolean"
  ) {
    return null;
  }

  const board = parseBoardCode(input.boardCode);
  if (board === null) return null;

  const initial = createGameFromCode(board);
  const selection = decodeSelection(input.selection, initial.board.deck.length);
  const matched = decodeMatched(input.matched, initial.board.deck);
  if (
    selection === null ||
    matched === null ||
    selectionTouchesMatched(selection, matched) ||
    !isConsistent(input.started, input.moves, input.elapsedMs, selection, matched.length / 2, initial.board.deck.length)
  ) {
    return null;
  }

  const restored: GameState = {
    board: initial.board,
    matched,
    selection: Object.freeze(selection),
    moves: input.moves,
    elapsedMs: input.elapsedMs,
    started: input.started,
  };

  return isWon(restored) && selection.kind !== "closed" ? null : Object.freeze(restored);
}

function selectionTouchesMatched(selection: GameSelection, matched: readonly number[]): boolean {
  if (selection.kind === "closed") return false;
  if (selection.kind === "one") return matched.includes(selection.index);
  return matched.includes(selection.first) || matched.includes(selection.second);
}

function isConsistent(
  started: boolean,
  moves: number,
  elapsedMs: number,
  selection: GameSelection,
  pairs: number,
  cardCount: number,
): boolean {
  if (!started) {
    return moves === 0 && elapsedMs === 0 && pairs === 0 && selection.kind === "closed";
  }

  if (selection.kind === "mismatch" && moves < pairs + 1) return false;
  if (moves < pairs) return false;
  if (moves === 0 && selection.kind !== "one") return false;
  if (pairs === cardCount / 2 && selection.kind !== "closed") return false;
  return true;
}

