import { describe, expect, it } from "vitest";
import { createGame } from "./create.ts";
import { advanceGame } from "./clock.ts";
import { activateCard, isWon } from "./transition.ts";

function game() {
  const state = createGame("np1-4-1");
  if (state === null) throw new Error("Test board should be valid.");
  return state;
}

describe("card transitions", () => {
  it("ignores repeating the first card and counts only the second activation", () => {
    const initial = game();
    const first = activateCard(initial, 0);
    expect(activateCard(first, 0)).toBe(first);
    expect(first.moves).toBe(0);
    expect(activateCard(first, 11).moves).toBe(1);
  });

  it("matches immediately and preserves the match after later turns", () => {
    const first = activateCard(game(), 0);
    const match = activateCard(first, 11);
    expect(match.matched).toEqual([0, 11]);
    expect(match.selection.kind).toBe("closed");
    expect(match.moves).toBe(1);
    expect(isWon(match)).toBe(false);
  });

  it("blocks mismatch activations and closes exactly at 800 active ms", () => {
    const first = activateCard(game(), 1);
    const miss = activateCard(first, 2);
    expect(miss.selection).toEqual({ kind: "mismatch", first: 1, second: 2, remainingMs: 800 });
    expect(activateCard(miss, 0)).toBe(miss);
    const waiting = advanceGame(miss, 799);
    expect(waiting.selection).toEqual({ kind: "mismatch", first: 1, second: 2, remainingMs: 1 });
    expect(advanceGame(waiting, 1).selection.kind).toBe("closed");
  });

  it("caps elapsed time and keeps it stopped after a win", () => {
    const nearCap = {
      ...activateCard(game(), 0),
      elapsedMs: 359999998,
    };
    const capped = advanceGame(nearCap, 10);
    expect(capped.elapsedMs).toBe(359999999);
    expect(advanceGame(capped, 10).elapsedMs).toBe(359999999);
  });
});
import { describe, expect, it } from "vitest";
import { replayGame } from "./replay.ts";

describe("version 1 replay", () => {
  it("matches the documented example result", () => {
    const replay = JSON.stringify({
      version: 1,
      boardCode: "np1-4-1",
      actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }],
      endMs: 800,
    });
    expect(replayGame(replay)).toMatchObject({
      matched: [0, 11],
      moves: 1,
      elapsedMs: 800,
    });
  });

  it("resolves the mismatch before an activation at the exact timeout", () => {
    const replay = JSON.stringify({
      version: 1,
      boardCode: "np1-4-1",
      actions: [
        { atMs: 0, index: 1 },
        { atMs: 0, index: 2 },
        { atMs: 800, index: 0 },
      ],
      endMs: 800,
    });
    expect(replayGame(replay)?.selection).toEqual({ kind: "one", index: 0 });
  });

  it("uses safe replay time beyond the displayed clock cap to close mismatches", () => {
    const replay = JSON.stringify({
      version: 1,
      boardCode: "np1-4-1",
      actions: [
        { atMs: 0, index: 1 },
        { atMs: 0, index: 2 },
        { atMs: Number.MAX_SAFE_INTEGER, index: 0 },
      ],
      endMs: Number.MAX_SAFE_INTEGER,
    });
    const result = replayGame(replay);
    expect(result?.elapsedMs).toBe(359999999);
    expect(result?.selection).toEqual({ kind: "one", index: 0 });
  });

  it("rejects unknown fields, bad action order and oversized inputs", () => {
    const base = { version: 1, boardCode: "np1-4-1", actions: [], endMs: 0 };
    expect(replayGame(JSON.stringify({ ...base, extra: true }))).toBeNull();
    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 0, index: 0, extra: true }] }))).toBeNull();
    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 2, index: 0 }, { atMs: 1, index: 1 }] }))).toBeNull();
    expect(replayGame(`${JSON.stringify(base)}${" ".repeat(1048576)}`)).toBeNull();
  });
});

