import { useEffect, useMemo, useRef, useSyncExternalStore } from "react";
import { GameSession, type GameSessionView } from "./session.ts";

export interface GameSessionActions {
  readonly activateCard: (index: number) => void;
  readonly changeSize: (size: number) => void;
  readonly exportSnapshot: () => string;
  readonly loadBoard: (draft: string) => void;
  readonly loadSnapshot: (text: string) => void;
  readonly newGame: () => void;
  readonly restart: () => void;
  readonly resume: () => void;
}

export type GameSessionApi = GameSessionView & GameSessionActions;

export function useGameSession(): GameSessionApi {
  const reference = useRef<GameSession | null>(null);
  if (reference.current === null) reference.current = new GameSession();
  const session = reference.current;
  const view = useSyncExternalStore(
    session.subscribe,
    session.getSnapshot,
    session.getSnapshot,
  );

  useEffect(() => {
    const updateVisibility = (): void => {
      session.setVisible(document.visibilityState !== "hidden", performance.now());
    };
    updateVisibility();
    document.addEventListener("visibilitychange", updateVisibility);
    return () => document.removeEventListener("visibilitychange", updateVisibility);
  }, [session]);

  useEffect(() => {
    if (!view.running) return undefined;
    const revision = view.dealRevision;
    let active = true;
    let frame = 0;
    const update = (timestamp: number): void => {
      if (!active || session.getSnapshot().dealRevision !== revision) return;
      session.tick(timestamp);
      if (session.shouldTick()) frame = requestAnimationFrame(update);
    };
    frame = requestAnimationFrame(update);
    return () => {
      active = false;
      cancelAnimationFrame(frame);
    };
  }, [session, view.dealRevision, view.running]);

  const actions = useMemo<GameSessionActions>(() => ({
    activateCard: (index) => session.activateCard(index),
    changeSize: (size) => session.changeSize(size),
    exportSnapshot: () => session.exportSnapshot(),
    loadBoard: (draft) => session.loadBoard(draft),
    loadSnapshot: (text) => session.loadSnapshot(text),
    newGame: () => session.newGame(),
    restart: () => session.restart(),
    resume: () => session.resume(),
  }), [session]);

  return { ...view, ...actions };
}

export class ActiveClock {
  private lastNow: number;
  private fractionalMs = 0;

  public constructor(now: number) {
    this.lastNow = Number.isFinite(now) ? now : 0;
  }

  public elapsedWholeMilliseconds(now: number, active: boolean): number {
    const current = Number.isFinite(now) ? Math.max(this.lastNow, now) : this.lastNow;
    if (!active) {
      this.lastNow = current;
      return 0;
    }

    const elapsed = current - this.lastNow + this.fractionalMs;
    const wholeMilliseconds = Math.floor(elapsed);
    this.fractionalMs = elapsed - wholeMilliseconds;
    this.lastNow = current;
    return wholeMilliseconds;
  }

  public anchor(now: number): void {
    if (Number.isFinite(now)) this.lastNow = Math.max(this.lastNow, now);
  }

  public reset(now: number): void {
    this.fractionalMs = 0;
    this.anchor(now);
  }
}
import { isWon, pairCount, type GameState } from "../state.ts";
import type { BoardSize } from "../board/sizes.ts";
import type { GameSessionView, SessionAnnouncement } from "./types.ts";

export function createSessionView(
  game: GameState,
  size: BoardSize,
  bestMoves: number | null,
  dealRevision: number,
  paused: boolean,
  visible: boolean,
  celebrationId: number,
  announcement: SessionAnnouncement | null,
  status: string,
): GameSessionView {
  const won = isWon(game);
  return Object.freeze({
    game,
    size,
    bestMoves,
    dealRevision,
    paused,
    visible,
    running: visible && !paused && game.started && !won,
    pairCount: pairCount(game),
    totalPairs: game.board.deck.length / 2,
    won,
    celebrationId,
    announcement,
    status,
  });
}
import { BOARD_SIZES, isBoardSize, type BoardSize } from "../board/sizes.ts";
import { advanceGame } from "../clock.ts";
import { boardCode, gameFor, randomSeed, startNow } from "./board.ts";
import { decodeSnapshot, encodeSnapshot } from "../snapshot.ts";
import { activateCard } from "../transition.ts";
import { isWon, pairCount, type GameState } from "../state.ts";
import { describeTurn } from "./turn.ts";
import type { GameSessionView, SessionAnnouncement, SessionOptions } from "./types.ts";
import {
  browserStorage,
  emptyPreferences,
  readPreferences,
  writePreferences,
  type StorageLike,
  type StoredPreferences,
} from "./storage.ts";

export class GameSession {
  private readonly clock: () => number;
  private readonly seedSource: () => number;
  private readonly storage: StorageLike | undefined;
  private preferences: StoredPreferences;
  private game: GameState;
  private paused = false;
  private visible = true;
  private dealRevision = 0;
  private celebrationId = 0;
  private announcementId = 0;
  private announcement: SessionAnnouncement | null = null;
  private status = "";
  private lastNow: number;
  private fractionalMs = 0;
  private view: GameSessionView;
  private readonly listeners = new Set<(view: GameSessionView) => void>();

  public constructor(options: SessionOptions = {}) {
    this.clock = options.now ?? (() => performance.now());
    this.seedSource = options.seedSource ?? randomSeed;
    this.storage = options.storage === null
      ? undefined
      : options.storage ?? browserStorage();
    this.preferences = this.storage === undefined
      ? emptyPreferences()
      : readPreferences(this.storage);
    this.game = gameFor(boardCode(this.preferences.size, this.seedSource));
    this.lastNow = startNow(this.clock);
    this.view = this.makeView();
  }

  public getSnapshot = (): GameSessionView => this.view;

  public subscribe = (listener: (view: GameSessionView) => void): (() => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  public shouldTick(): boolean {
    return this.visible && !this.paused && this.game.started && !isWon(this.game);
  }

  public activateCard(index: number): void {
    this.syncAt(this.clock());
    if (this.paused || !this.visible) return;

    const before = this.game;
    const after = activateCard(before, index);
    if (after === before) return;
    this.game = after;

    if (before.selection.kind === "one") {
      const result = describeTurn(before, after);
      if (result !== null) {
        if (result.won) {
          this.celebrationId += 1;
          this.recordBest(after);
        }
        this.announcementId += 1;
        this.announcement = { id: this.announcementId, text: result.message };
      }
    }
    this.publish();
  }

  public newGame(): void {
    this.replaceGame(boardCode(this.game.board.size, this.seedSource, this.game.board.code));
  }

  public restart(): void {
    this.replaceGame(this.game.board.code);
  }

  public changeSize(value: number): void {
    if (!isBoardSize(value) || value === this.game.board.size) return;
    this.replaceGame(boardCode(value, this.seedSource, this.game.board.code));
    this.updatePreferences({ ...this.preferences, size: value });
  }

  public loadBoard(draft: string): void {
    const code = draft.trim();
    const game = createGame(code);
    if (game === null) {
      this.setStatus("Invalid board code.");
      return;
    }
    this.replaceGame(code);
    this.updatePreferences({ ...this.preferences, size: game.board.size });
  }

  public exportSnapshot(): string {
    this.syncAt(this.clock());
    return encodeSnapshot(this.game);
  }

  public loadSnapshot(text: string): void {
    const game = decodeSnapshot(text);
    if (game === null) {
      this.setStatus("Invalid snapshot.");
      return;
    }

    this.replaceGame(game.board.code, game, !isWon(game));
    this.updatePreferences({ ...this.preferences, size: game.board.size });
    this.setStatus(isWon(game)
      ? "Loaded completed snapshot."
      : "Loaded snapshot. Select Resume to continue.");
  }

  public resume(): void {
    if (!this.paused || isWon(this.game)) return;
    this.syncAnchor(this.clock());
    this.paused = false;
    this.publish();
  }

  public setVisible(visible: boolean, now: number): void {
    if (this.visible === visible) return;
    this.syncAt(now);
    this.visible = visible;
    this.syncAnchor(now);
    this.publish();
  }

  public tick(now: number): void {
    this.syncAt(now);
  }

  private syncAt(now: number): void {
    const current = Number.isFinite(now) ? Math.max(this.lastNow, now) : this.lastNow;
    if (!this.shouldTick()) {
      this.syncAnchor(current);
      return;
    }

    const elapsed = current - this.lastNow + this.fractionalMs;
    const wholeMilliseconds = Math.floor(elapsed);
    this.fractionalMs = elapsed - wholeMilliseconds;
    this.lastNow = current;
    if (wholeMilliseconds <= 0) return;

    const before = this.game;
    const after = advanceGame(before, wholeMilliseconds);
    if (after.elapsedMs === before.elapsedMs && after.selection === before.selection) return;
    this.game = after;
    this.publish();
  }

  private syncAnchor(now: number): void {
    if (Number.isFinite(now)) this.lastNow = Math.max(this.lastNow, now);
  }

  private replaceGame(code: string, game = gameFor(code), paused = false): void {
    this.syncAnchor(this.clock());
    this.game = game;
    this.paused = paused;
    this.fractionalMs = 0;
    this.dealRevision += 1;
    this.celebrationId = 0;
    this.announcement = null;
    this.status = "";
    this.publish();
  }

  private recordBest(game: GameState): void {
    const currentBest = this.preferences.bestMoves[game.board.size];
    if (currentBest !== undefined && currentBest <= game.moves) return;
    const bestMoves = { ...this.preferences.bestMoves, [game.board.size]: game.moves };
    this.updatePreferences({ ...this.preferences, bestMoves });
  }

  private updatePreferences(preferences: StoredPreferences): void {
    this.preferences = preferences;
    writePreferences(this.storage, preferences);
    this.publish();
  }

  private setStatus(status: string): void {
    this.status = status;
    this.setAnnouncement(status);
    this.publish();
  }

  private makeView(): GameSessionView {
    const won = isWon(this.game);
    return Object.freeze({
      game: this.game,
      size: this.game.board.size,
      bestMoves: this.preferences.bestMoves[this.game.board.size] ?? null,
      dealRevision: this.dealRevision,
      paused: this.paused,
      visible: this.visible,
      running: this.shouldTick(),
      pairCount: pairCount(this.game),
      totalPairs: this.game.board.deck.length / 2,
      won,
      celebrationId: this.celebrationId,
      announcement: this.announcement,
      status: this.status,
    });
  }

  private publish(): void {
    this.view = this.makeView();
    for (const listener of this.listeners) listener(this.view);
  }
}

