      onClick={(event) => handleClick(event, () => onActivate(index))}
      onFocus={() => onFocusCard(index)}
      onKeyDown={(event) => handleKeyDown(event, index, size, onMoveFocus)}
      ref={ref}
      tabIndex={tabStop ? 0 : -1}
